INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7401, '1 Samuel 26:5', '1 Samuel', 26, 5, '&nbsp;نو هغه راووتلو او هم هغه ځائ ته راغلو چرته چې د ساؤل او د ساؤل د لښکر مشر د نير زوئ ابنير ملاست وو. ساؤل په کېمپ کښې دننه څملاستو او د هغۀ سړو ګېرچاپېره خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7402, '1 Samuel 26:6', '1 Samuel', 26, 6, '&nbsp;بيا داؤد د اخيمُلک حِتى او د يوآب ورور ابيشى (د دوئ مور ضروياه وه) نه تپوس وکړو، ”په تاسو دواړو کښې به کوم يو ما سره د ساؤل کېمپ ته لاړ شى؟“ ابيشى ورته په جواب کښې ووئيل، ”زۀ به درسره لاړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7403, '1 Samuel 26:7', '1 Samuel', 26, 7, '&nbsp;نو په هغه شپه داؤد او ابيشے د ساؤل خېمو ته ننوتل او وې ليدل چې ساؤل د کېمپ په مينځ کښې ملاست وو او د هغۀ نېزه د هغۀ د سر سره نزدې په زمکه کښې ښخه وه. ابنير او فوجيان د هغۀ نه ګېرچاپېره ملاست وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7404, '1 Samuel 26:8', '1 Samuel', 26, 8, '&nbsp;ابيشى داؤد ته ووئيل چې، ”خُدائ پاک تا له خپل دشمن نن په لاس کښې درکړے دے. اوس ما له اجازت راکړه چې هم د هغۀ خپله نېزه ترې نه په بل مخ بوټه وباسم او صِرف په يو غرب سره به يې داسې کړم چې د زمکې نه به پاڅېدلے نۀ شى، د دوېم ځل وهلو حاجت به يې هم راته نۀ پېښيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7405, '1 Samuel 26:9', '1 Samuel', 26, 9, '&nbsp;خو داؤد ورته وفرمائيل، ”تۀ هغه مۀ وژنه. بې‌شکه مالِک خُدائ به هغه چا له سزا ورکوى چې څوک هم د هغۀ خوښ کړے شوى بادشاه ته نقصان رسوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7406, '1 Samuel 26:10', '1 Samuel', 26, 10, '&nbsp;داؤد وفرمائيل، ”ما ته پته ده چې مالِک خُدائ به په خپله ساؤل مړ کوى، کۀ هغه په خپل مرګ مړ شى او يا کۀ په جنګ کښې مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7407, '1 Samuel 26:11', '1 Samuel', 26, 11, '&nbsp;مالِک خُدائ دې نۀ کړى چې هغه چا له د نقصان رسولو کوشش وکړم څوک چې مالِک خُدائ بادشاه جوړ کړے دے. راځئ چې د هغۀ نېزه او د اوبو منګے راواخلو او لاړ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7408, '1 Samuel 26:12', '1 Samuel', 26, 12, '&nbsp;نو داؤد نېزه او د اوبو منګے واخستلو چې د ساؤل د سر سره نزدې پراتۀ وو او هغه او ابيشے لاړل. هيچا دا ونۀ ليدل او نۀ ورته پته ولګېده چې څۀ وشول او نۀ څوک پاڅېدل، هغوئ ټول په خوږ خوب اودۀ وُو، ځکه چې مالِک خُدائ په هغه ټولو باندې دروند خوب رالېږلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7409, '1 Samuel 26:13', '1 Samuel', 26, 13, '&nbsp;بيا داؤد د وادۍ نه واوړېدو او د بل غر سر ته لاړو، کوم ځائ چې لږ لرې وو او د خطرې نه بهر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7410, '1 Samuel 26:14', '1 Samuel', 26, 14, '&nbsp;او د ساؤل فوجيانو او ابنير ته يې چغه ووهله، ”ابنيره، تۀ زما آواز اورې؟“ ابنير تپوس وکړو، ”دا چغې څوک وهى چې بادشاه راپاڅوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7411, '1 Samuel 26:15', '1 Samuel', 26, 15, '&nbsp;داؤد ورته وفرمائيل، ”ابنيره، په بنى اِسرائيلو کښې ستا په شان تکړه سړے څوک شته؟ نو تۀ خپل نېک يعنې بادشاه ولې نۀ بچ کوې؟ دا اوس اوس څوک خېمو ته لاړل چې ستا نېک ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7412, '1 Samuel 26:16', '1 Samuel', 26, 16, '&nbsp;ابنيره، تۀ په خپله ذمه وارۍ کښې ناکام شوې. زۀ په ژوندى مالِک خُدائ قسم خورم چې تاسو ټول د مرګ لائق يئ، ځکه چې تاسو خپل نېک بچ نۀ کړو، کوم چې مالِک خُدائ بادشاه جوړ کړے دے. د بادشاه نېزه چرته ده؟ د اوبو منګے چرته دے چې د هغۀ د سر سره وو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7413, '1 Samuel 26:17', '1 Samuel', 26, 17, '&nbsp;ساؤل د داؤد آواز وپېژندو او تپوس يې ترې نه وکړو، ”داؤده، دا تۀ يې زما زويه؟“ داؤد ورته وفرمائيل، ”آو، بادشاه سلامت دا زۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7414, '1 Samuel 26:18', '1 Samuel', 26, 18, '&nbsp;او هغۀ دا هم وفرمائيل، ”زما نېک تر اوسه پورې په خپل خِدمت کوونکى پسې ولې ګرځى؟ ما څۀ کړى دى؟ ما کوم جرم کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7415, '1 Samuel 26:19', '1 Samuel', 26, 19, '&nbsp;بادشاه سلامت، زۀ چې څۀ وئيل غواړم نو هغه واوره. کۀ دا مالِک خُدائ وى چې تۀ يې زما خِلاف کړې، نو يوه نذرانه چې هغۀ ته پېش شى نو کېدے شى چې د هغۀ فېصله بدله شى، خو کۀ دا انسان کړى وى، نو په هغوئ دې د مالِک خُدائ لعنت راشى. ځکه چې هغوئ زۀ د مالِک خُدائ د مُلک نه وشړلم او راته يې ووئيل چې د پردو معبودانو عبادت کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7416, '1 Samuel 26:20', '1 Samuel', 26, 20, '&nbsp;زما وينه دې د مالِک خُدائ نه لرې په پردۍ خاوره نۀ توئيږى. د بنى اِسرائيلو بادشاه دې صِرف د يوې ورَږې د لټولو دپاره ولې راشى، لکه څوک چې په غرونو کښې د زرکې ښکار کوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7417, '1 Samuel 26:21', '1 Samuel', 26, 21, '&nbsp;ساؤل ورته ووئيل، ”ما ګناه کړې ده. زما زويه، داؤده. واپس راشه، زۀ به تا ته نقصان نۀ دررسوم، ځکه چې تا نن زما ژوند بچ کړو. زۀ کم عقل وم، ما يو بد عمل کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7418, '1 Samuel 26:22', '1 Samuel', 26, 22, '&nbsp;داؤد ورته وفرمائيل، ”بادشاه سلامت، ستا نېزه دا ده. ستا يو سړے دې راشى او دا دې واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7419, '1 Samuel 26:23', '1 Samuel', 26, 23, '&nbsp;مالِک خُدائ هغه چا له اجر ورکوى چې څوک وفادار او رښتونى وى. نن هغۀ ما له تۀ په لاس کښې راکړې، خو ما تا ته نقصان ونۀ رسولو، څوک چې مالِک خُدائ بادشاه جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7420, '1 Samuel 26:24', '1 Samuel', 26, 24, '&nbsp;لکه څنګه چې نن ما ستا ژوند بچ کړے دے، نو مالِک خُدائ دې هم هغه شان زما سره هم وکړى او چې د ټولو تکليفونو نه مې خلاص کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7421, '1 Samuel 26:25', '1 Samuel', 26, 25, '&nbsp;ساؤل داؤد ته ووئيل، ”زما زويه، خُدائ پاک دې تا له برکت درکړى. تۀ به په هر کار کښې کامياب يې.“ نو داؤد په خپله مخه لاړو او ساؤل کور ته واپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7422, '1 Samuel 27:1', '1 Samuel', 27, 1, '&nbsp;خو داؤد د خپل ځان سره وفرمائيل، ”په نن سبا کښې به ما ساؤل ووژنى. زما دپاره ښۀ خبره دا ده چې د فلستى علاقې ته وتښتم. نو ساؤل به د بنى اِسرائيل په مُلک کښې زما لټول پرېږدى او زۀ به بچ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7423, '1 Samuel 27:2', '1 Samuel', 27, 2, '&nbsp;نو داؤد او د هغۀ شپږ سوه سړى د جات بادشاه د معوک زوئ اکيس مُلک ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7424, '1 Samuel 27:3', '1 Samuel', 27, 3, '&nbsp;داؤد او د هغۀ سړى سره د خپلو کورَنو هلته په جات کښې دېره شول. د داؤد سره خپلې دوه ښځې وې، د يزرعيل اخينوعم او د نابال کونډه ابى‌جيل چې د کرمل وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7425, '1 Samuel 27:4', '1 Samuel', 27, 4, '&nbsp;کله چې ساؤل خبر شو چې داؤد جات ته تښتېدلے دے، نو ساؤل د هغۀ لټول پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7426, '1 Samuel 27:5', '1 Samuel', 27, 5, '&nbsp;داؤد اکيس ته وفرمائيل، ”کۀ تۀ زما سره ښېګړه کول غواړې نو ما له اجازت راکړه چې په يو وړوکى ښار کښې اوسېږم. صاحِبه، زما دپاره دا ضرورى نۀ ده چې زۀ تا سره په شاهى ښار کښې اوسېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7427, '1 Samuel 27:6', '1 Samuel', 27, 6, '&nbsp;نو اکيس هغۀ له د صِقلاج ښار ورکړو، نو په دې وجه د صِقلاج ښار تر ننه پورې د يهوداه د بادشاهانو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7428, '1 Samuel 27:7', '1 Samuel', 27, 7, '&nbsp;داؤد په فلستى مُلک کښې شپاړس مياشتې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7429, '1 Samuel 27:8', '1 Samuel', 27, 8, '&nbsp;په هغه وخت کښې داؤد او د هغۀ سړو په جسوريانو، جرزيانو، عماليقيانو باندې حملې کولې، چې هغوئ د ډېر وخت نه په هغه علاقه کښې اوسېدل. هغۀ به تر شور او لاندې مِصر پورې حملې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7430, '1 Samuel 27:9', '1 Samuel', 27, 9, '&nbsp;ټول سړى او ښځې به يې وژلې او د هغوئ ګډې، څاروى، خرۀ، اوښان او کپړې به يې ترې نه هم وړلې. بيا به واپس اکيس له راتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7431, '1 Samuel 27:10', '1 Samuel', 27, 10, '&nbsp;اکيس به د هغۀ نه تپوس کولو، ”دا ځل تۀ په کوم ځائ حملې کولو له تلے وې؟“ نو داؤد به ورته فرمائيل چې زۀ د يهوداه جنوبى حِصې يا د يرحمئيل قبيلې علاقې ته، يا هغې علاقې ته تلے وم چرته چې قينيان اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7432, '1 Samuel 27:11', '1 Samuel', 27, 11, '&nbsp;داؤد به هر څوک نر او ښځې وژل او هيڅ څوک به جات ته نۀ شُو تلے چې هغه يې خبر کړے وے چې هغۀ او د هغۀ سړو څۀ کړى دى. کله چې هغه په فلستى مُلک کښې اوسېدو نو داؤد به هر وخت هم دغه شان کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7433, '1 Samuel 27:12', '1 Samuel', 27, 12, '&nbsp;خو اکيس په داؤد اعتبار کولو او د خپل ځان سره يې ووئيل، ”د هغۀ خلق بنى اِسرائيليان د هغۀ نه دومره نفرت کوى چې هغه به ټول عُمر زما خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7434, '1 Samuel 28:1', '1 Samuel', 28, 1, '&nbsp;څۀ موده وروستو، فلستيانو خپل فوجيان راغونډ کړل چې د بنى اِسرائيلو سره جنګ وکړى او اکيس داؤد ته ووئيل، ”تا ته دا پته ده چې تۀ او ستا سړى به زما دپاره جنګېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7435, '1 Samuel 28:2', '1 Samuel', 28, 2, '&nbsp;داؤد ورته وفرمائيل، ”دا رښتيا دى، زۀ ستا خِدمت کوونکے يم او تۀ به په خپله وګورې چې زۀ څۀ کوم.“ اکيس ورته ووئيل، ”ټيک ده. زۀ به تا د ټول عُمر دپاره خپل حِفاظت کوونکے محافظ جوړ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7436, '1 Samuel 28:3', '1 Samuel', 28, 3, '&nbsp;نو سموئيل مړ شوے وو او ټولو بنى اِسرائيلو په هغۀ ژړا کړې وه او د هغۀ په خپل ښار راما کښې يې ښخ کړے وو. او ساؤل د اِسرائيل مُلک نه کوډګر او جادوګر شړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7437, '1 Samuel 28:4', '1 Samuel', 28, 4, '&nbsp;فلستى فوجيان راغونډ شول او د شونيم ښار سره يې نزدې خېمې ولګولې، ساؤل بنى اِسرائيليان راغونډ کړل او د جِلبوعه په غرۀ يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7438, '1 Samuel 28:5', '1 Samuel', 28, 5, '&nbsp;چې ساؤل د فلستيانو لښکر وليدو، نو هغه د يرې نه ولړزېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7439, '1 Samuel 28:6', '1 Samuel', 28, 6, '&nbsp;نو هغۀ د مالِک خُدائ نه تپوس وکړو چې څۀ وکړم. خو مالِک خُدائ بېخى جواب ورنۀ کړو، نۀ د خوبونو په ذريعه، نۀ د اُوريم او تميم استعمالولو او نۀ د پېغمبرانو په ذريعه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7440, '1 Samuel 28:7', '1 Samuel', 28, 7, '&nbsp;نو ساؤل خپلو آفسرانو له حُکم ورکړو، ”يوه کوډګره ښځه ولټوئ چې د مړو د روحونو سره مشورې کوى او زۀ به ورشم او مشوره به ورسره وکړم.“ هغوئ جواب ورکړو، ”په عين دور کښې يوه داسې ښځه شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7441, '1 Samuel 28:8', '1 Samuel', 28, 8, '&nbsp;نو ساؤل خپل ځان بدل کړو، هغۀ د شاهى جامو په ځائ عامې جامې واغوستلې او د تيارې نه پس هغه د خپلو دوو سړو سره هغه ښځې له مِلاوېدو له لاړو. هغۀ ورته ووئيل، ”زما دپاره د روحونو سره مشوره وکړه او ما ته ووايه چې څۀ کيږى. د هغه سړى روح راوغواړه چې زۀ يې نوم اخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7442, '1 Samuel 28:9', '1 Samuel', 28, 9, '&nbsp;ښځې جواب ورکړو، ”تا ته ښۀ پته ده چې ساؤل څۀ کړى دى هغۀ څنګه کوډګر او جادوګر د مُلک نه وشړل. نو بيا تۀ ولې زما د ګېرولو کوشش کوې او ما وژل غواړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7443, '1 Samuel 28:10', '1 Samuel', 28, 10, '&nbsp;بيا ساؤل قسم وخوړو او ورته يې ووئيل، ”زۀ د ژوندى مالِک خُدائ په نوم دا لوظ کوم چې د داسې کولو په وجه به تا ته سزا نۀ ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7444, '1 Samuel 28:11', '1 Samuel', 28, 11, '&nbsp;ښځې ترې نه تپوس وکړو، ”زۀ ستا دپاره د چا روح راوغواړم؟“ هغۀ جواب ورکړو، ”د سموئيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7445, '1 Samuel 28:12', '1 Samuel', 28, 12, '&nbsp;کله چې ښځې سموئيل وليدو نو هغې چغه کړه او ساؤل ته يې ووئيل، ”تا زۀ ولې دوکه کړم؟ تۀ ساؤل بادشاه يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7446, '1 Samuel 28:13', '1 Samuel', 28, 13, '&nbsp;بادشاه هغې ته ووئيل، ”مۀ يرېږه، تۀ څۀ ګورې؟“ هغې ورته په جواب کښې ووئيل، ”زۀ يو روح وينم چې د زمکې نه راوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7447, '1 Samuel 28:14', '1 Samuel', 28, 14, '&nbsp;هغۀ ترې نه تپوس وکړو، ”هغه د چا په شان دے؟“ هغې ورته ووئيل، ”يو بوډا سړے راروان دے او چُوغه يې اغوستې ده.“ نو ساؤل ته پته ولګېده چې دا سموئيل دے او هغه د عزت نه زمکې ته ټيټ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7448, '1 Samuel 28:15', '1 Samuel', 28, 15, '&nbsp;سموئيل، ساؤل ته وفرمائيل، ”تا ما له تکليف ولې راکړو؟ تا زۀ واپس ولې راوستلم؟“ ساؤل ورته ووئيل، ”زۀ په لوئ تکليف کښې يم. فلستيان زما سره په جنګ دى او خُدائ پاک زۀ پرېښے يم. هغۀ ما له نور جواب نۀ راکولو، نۀ د پېغمبرانو په ذريعه او نۀ د خوبونو په ذريعه. نو ما تۀ راوغوښتلې، دا د دې دپاره چې ما ته ووائې چې زۀ څۀ وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7449, '1 Samuel 28:16', '1 Samuel', 28, 16, '&nbsp;سموئيل ورته وفرمائيل، ”چې مالِک خُدائ پرېښے يې او هغه ستا دشمن شوے دے نو زۀ دې ولې راوغوښتلم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7450, '1 Samuel 28:17', '1 Samuel', 28, 17, '&nbsp;مالِک خُدائ تا سره هغه څۀ کړى دى چې هغۀ زما په ذريعه تا ته فرمائيلى وُو. هغۀ ستا نه بادشاهى اخستې ده او داؤد له يې ورکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7451, '1 Samuel 28:18', '1 Samuel', 28, 18, '&nbsp;تا د مالِک خُدائ د حُکم نافرمانى کړې ده ځکه چې تا عماليقيان او د هغوئ هر څۀ تباه نۀ کړل. نو نن دا ځکه مالِک خُدائ تا سره داسې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7452, '1 Samuel 28:19', '1 Samuel', 28, 19, '&nbsp;هغه به تا او بنى اِسرائيليان فلستيانو له په لاس کښې ورکړى. سبا به تۀ او ستا زامن ما سره شريک شئ او مالِک خُدائ به د بنى اِسرائيلو لښکر هم فلستيانو له په لاس کښې ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7453, '1 Samuel 28:20', '1 Samuel', 28, 20, '&nbsp;ساؤل ناڅاپه راپرېوتو او په زمکه باندې اوږد اوږد وغزېدو، چې سموئيل څۀ فرمائيلى وُو نو د هغې په وجه ويرېدو. هغه کمزورے وو، ځکه چې هغۀ ټوله ورځ او ټوله شپه هيڅ هم نۀ وُو خوړلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7454, '1 Samuel 28:21', '1 Samuel', 28, 21, '&nbsp;هغه ښځه ساؤل له ورغله او وې ليدل چې هغه يرېدلے وو، نو هغې ورته ووئيل، ”صاحِبه، تا چې څۀ وئيلى دى د هغې په وجه ما خپل ژوند په خطره کښې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7455, '1 Samuel 28:22', '1 Samuel', 28, 22, '&nbsp;نو اوس ستا وار دے چې زما خبرې ته غوږ ونيسې. زۀ به ستا دپاره لږ خوراک تيار کړم. تۀ خامخا څۀ وخوره چې د سفر کولو جوګه شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7456, '1 Samuel 28:23', '1 Samuel', 28, 23, '&nbsp;ساؤل اِنکار وکړو او وې وئيل چې هيڅ به هم نۀ خورم. خو د هغۀ آفسرانو هم ورته ووئيل چې څۀ وخوره. آخر هغۀ د هغوئ خبره ومنله او د زمکې نه پاڅېدو او په کټ کښې کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7457, '1 Samuel 28:24', '1 Samuel', 28, 24, '&nbsp;هغه ښځې زر يو سخے حلال کړو کوم چې هغې ښۀ څورب کړے وو. بيا هغې لږ اوړۀ واخستل، تيار يې کړل او پتيره روټۍ يې ترې نه پخه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7458, '1 Samuel 28:25', '1 Samuel', 28, 25, '&nbsp;هغې خوراک د ساؤل او د هغۀ د آفسرانو په وړاندې کېښودو او هغوئ وخوړو. او هغوئ هم په هغه شپه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7459, '1 Samuel 29:1', '1 Samuel', 29, 1, '&nbsp;فلستيانو خپل ټول فوجيان افيق ته راغونډ کړل او بنى اِسرائيلو په يزرعيل کښې د چينې سره خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7460, '1 Samuel 29:2', '1 Samuel', 29, 2, '&nbsp;پينځۀ فلستى بادشاهان د خپلو سوونو او زرګونو سړو د ډلو سره لاړل، داؤد او د هغۀ سړى د اکيس بادشاه سره شا ته روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7461, '1 Samuel 29:3', '1 Samuel', 29, 3, '&nbsp;فلستى مشرانو هغوئ وليدل او تپوس يې وکړو، ”دا عبرانيان دلته څۀ کوى؟“ اکيس ورته ووئيل چې، ”دا داؤد دے چې د بنى اِسرائيلو د بادشاه ساؤل يو آفسر دے. اوس هغه زما سره د ډېر وخت نه دے. د کومې ورځې نه چې هغه ما له راغلے دے نو هغۀ داسې يو کار هم نۀ دے کړے چې زۀ يې يوه غلطى راوباسم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7462, '1 Samuel 29:4', '1 Samuel', 29, 4, '&nbsp;خو فلستى مشران اکيس ته په غصه وُو او هغۀ ته يې ووئيل، ”دا کس واپس هغه ښار ته ولېږه کوم چې تا ورکړے دے. هغه مۀ پرېږده چې مونږ سره جنګ له لاړ شى، کېدے شى چې هغه په جنګ کښې زمونږ خِلاف شى. په دې کښې څۀ شک نشته چې هغه به د خپل نېک خوشحالولو دپاره زمونږ د سړو سرونه قلم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7463, '1 Samuel 29:5', '1 Samuel', 29, 5, '&nbsp;آخر دا هم هغه داؤد دے، چې د هغۀ په حقله ښځې په ګډېدو کښې سندره وئيلې چې ساؤل زرګونه وژلى دى، خو داؤد يو په لس د هغې نه زيات وژلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7464, '1 Samuel 29:6', '1 Samuel', 29, 6, '&nbsp;اکيس داؤد راوغوښتلو او ورته يې ووئيل، ”زۀ په ژوندى مالِک خُدائ قسم کوم چې تۀ زما وفادار يې، او زۀ به خوشحاله وم چې تۀ ما سره تلے وې او په دې جنګ کښې دې زما ملګرتيا کړے وے. تۀ چې د کومې ورځې نه ما له راغلے يې ما په تا کښې هيڅ غلطى نۀ ده موندلې. خو هغه نور بادشاهان تا نۀ منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7465, '1 Samuel 29:7', '1 Samuel', 29, 7, '&nbsp;نو په خېر سره واپس کور ته لاړ شه او داسې يو کار هم مۀ کوه چې هغوئ پرې خفه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7466, '1 Samuel 29:8', '1 Samuel', 29, 8, '&nbsp;داؤد جواب ورکړو، ”صاحِبه، ما څۀ بد کړى دى؟ کۀ داسې وى لکه چې تا ووئيل چې د کومې ورځې نه ما ستا خِدمت شروع کړے دے او تا په ما کښې هيڅ غلطى نۀ وى موندلې، نو ما له تا سره تلل ولې نۀ دى په کار، چې تۀ زما نېک او بادشاه يې، د دې دپاره چې زۀ ستا د دشمنانو سره جنګ وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7467, '1 Samuel 29:9', '1 Samuel', 29, 9, '&nbsp;اکيس ورته ووئيل، ”زۀ دا منم، زۀ تا د خُدائ پاک د فرښتې په شان وفادار ګڼم. خو هغه نورو بادشاهانو وئيلى دى چې تۀ زمونږ سره جنګ له نۀ شې تلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7468, '1 Samuel 29:10', '1 Samuel', 29, 10, '&nbsp;نو داؤده، تاسو ټول چا چې ساؤل پرېښے دے او ما له راغلى يئ، سبا سحر وختى پاڅئ او چې څنګه رڼا شى نو لاړ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7469, '1 Samuel 29:11', '1 Samuel', 29, 11, '&nbsp;نو داؤد او د هغۀ سړى په ورپسې ورځ سحر وختى روان شول چې فلستى مُلک ته واپس لاړ شى او فلستيان يزرعيل ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7470, '1 Samuel 30:1', '1 Samuel', 30, 1, '&nbsp;نو درې ورځې پس داؤد او د هغۀ سړى صِقلاج ته راورسېدل او پته ورته ولګېده چې عماليقيانو د يهوداه جنوبى علاقه نيولې ده او په صِقلاج يې حمله کړې ده. هغوئ ښار سوزولے وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7471, '1 Samuel 30:2', '1 Samuel', 30, 2, '&nbsp;او ټولې زنانه او ټول ماشومان نيولى وُو، هغوئ څوک وژلى نۀ وُو، خو چې کله تلل نو ټول يې د ځان سره بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7472, '1 Samuel 30:3', '1 Samuel', 30, 3, '&nbsp;کله چې داؤد او د هغۀ سړى راورسېدل، نو هغوئ ته پته ولګېده چې ښار سوزولے شوے وو او د هغوئ ښځې، زامن او لوڼه بوتلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7473, '1 Samuel 30:4', '1 Samuel', 30, 4, '&nbsp;داؤد او د هغۀ سړو ژړا شروع کړه او تر هغې پورې يې نۀ بس کوله چې د هغوئ د ژړا زور ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7474, '1 Samuel 30:5', '1 Samuel', 30, 5, '&nbsp;د داؤد دوه ښځې، اخينوعم او ابى‌جيل هم بوتلے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7475, '1 Samuel 30:6', '1 Samuel', 30, 6, '&nbsp;داؤد اوس په سخته خطره کښې وو، ځکه چې د هغۀ ټول سړى د خپلو بچو په وجه سخت غصه وُو او هغوئ هغه سنګسارول غوښتل، خو مالِک خُدائ د داؤد خُدائ پاک د هغۀ ايمان مضبوط کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7476, '1 Samuel 30:7', '1 Samuel', 30, 7, '&nbsp;داؤد د اخيمُلک زوئ ابياتار اِمام ته وفرمائيل، ”پېش بند ما له راوړه.“ نو ابياتار ورله پېش بند وروړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7477, '1 Samuel 30:8', '1 Samuel', 30, 8, '&nbsp;داؤد د مالِک خُدائ نه تپوس وکړو، ”زۀ د هغوئ په فوجيانو پسې لاړ شم څۀ؟ زۀ به هغوئ ته ورورسېږم؟“ نو هغۀ جواب ورکړو، ”ورپسې لاړ شه، تۀ به ورورسېږې او قېديان به ترې نه خلاص کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7478, '1 Samuel 30:9', '1 Samuel', 30, 9, '&nbsp;نو داؤد او د هغۀ شپږ سوه سړى روان شول او چې هغوئ د بسور ولې ته ورسېدل، نو څۀ هلته پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7479, '1 Samuel 30:10', '1 Samuel', 30, 10, '&nbsp;داؤد د څلورو سوو سړو سره په خپله مخه روان وو، هغه نور دوه سوه سړى ډېر زيات ستړى وُو چې د ولې نه نۀ شُو اوړېدلے نو هغوئ وروستو پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7480, '1 Samuel 30:11', '1 Samuel', 30, 11, '&nbsp;د داؤد سړو په هغه مُلک کښې يو مِصرے زلمے وليدو او داؤد له يې راوستو. هغوئ ورله څۀ خوراک او اوبۀ ورکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7481, '1 Samuel 30:12', '1 Samuel', 30, 12, '&nbsp;څۀ اوچ اينځر او دوه موټى کشمش يې هم ورله ورکړل. کله چې هغۀ خوراک وکړو، نو هغه بيا تکړه شو، د هغۀ سره پوره درې ورځې د خوراک څښاک هيڅ هم نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7482, '1 Samuel 30:13', '1 Samuel', 30, 13, '&nbsp;داؤد ترې نه تپوس وکړو، ”ستا نېک څوک دے او تۀ د کوم ځائ يې؟“ هغۀ ورته ووئيل، ”زۀ د مِصر يم او د يو عماليقى غلام يم. زما نېک زۀ درې ورځې مخکښې د ځان نه شاته پرېښے يم ځکه چې زۀ بيمار وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7483, '1 Samuel 30:14', '1 Samuel', 30, 14, '&nbsp;مونږ د يهوداه په جنوبى حِصه کښې د چريتيانو علاقه او د کالب د قبيلې په علاقه باندې حمله کړې وه او صِقلاج مو سوزولے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7484, '1 Samuel 30:15', '1 Samuel', 30, 15, '&nbsp;داؤد ترې نه تپوس وکړو، ”تۀ به ما د هغه لښکر پورې بوځې؟“ هغۀ ورته ووئيل، ”کۀ تۀ ما سره د خُدائ پاک په نوم وعده وکړې چې تۀ به ما نۀ وژنې او نۀ به مې خپل نېک ته حواله کوې نو زۀ به تا بوځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7485, '1 Samuel 30:16', '1 Samuel', 30, 16, '&nbsp;نو داؤد يې ورله بوتلو. هغه فوجيان په هر ځائ کښې خوارۀ وارۀ وُو، خوراک څښاک يې کولو او د بې‌شمېره مالِ غنيمت خوشحالى يې کوله، چې هغوئ د فلستيانو او يهوداه په مُلک کښې نيولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7486, '1 Samuel 30:17', '1 Samuel', 30, 17, '&nbsp;په ورپسې ورځ سحر وختى داؤد په هغوئ حمله وکړه او تر ماښامه پورې يې ورسره جنګ وکړو. د څلورو سوو زلمو نه بغېر چې هغوئ په اوښانو سوارۀ او لرې وُو، بل يو کس هم ونۀ تښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7487, '1 Samuel 30:18', '1 Samuel', 30, 18, '&nbsp;داؤد سره د خپلو دوو ښځو هغه هر يو کس او هر يو څيز بچ کړو چې عماليقيانو وړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7488, '1 Samuel 30:19', '1 Samuel', 30, 19, '&nbsp;يو څيز هم ورک نۀ شو کۀ هغه وړوکے وو يا غټ. داؤد ته د خپلو ټولو سړو زامن او لوڼه واپس مِلاو شول او هغه ټول مالِ غنيمت هم، کوم چې عماليقيانو وړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7489, '1 Samuel 30:20', '1 Samuel', 30, 20, '&nbsp;هغۀ ټولې ګډې او څاروى واپس واخستل، د هغۀ سړو ټول څاروى د هغوئ په مخکښې روان کړل او هغوئ او وئيل چې، ”دا د داؤد مالِ غنيمت دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7490, '1 Samuel 30:21', '1 Samuel', 30, 21, '&nbsp;نو داؤد هغه دوو سوو سړو له واپس لاړو چې هغوئ ډېر کمزورى شوى وُو او د تلو نۀ وُو او د بسور ولې سره وروستو پاتې وُو. هغوئ د داؤد او د هغۀ سړو سره مِلاوېدو دپاره وړاندې راغلل، داؤد هغوئ له ورَغلو او هغوئ ته يې تود هرکلے ووئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7491, '1 Samuel 30:22', '1 Samuel', 30, 22, '&nbsp;خو څۀ خرابو او بې‌کاره سړو ووئيل کوم چې د داؤد سره تلى وُو، ”هغوئ مونږ سره لا نۀ ړل، نو مونږ به هغوئ له د مالِ غنيمت نه څۀ نۀ ورکوو. هغوئ دې خپلې ښځې او بچى ځان سره کړى او په خپله مخه دې ځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7492, '1 Samuel 30:23', '1 Samuel', 30, 23, '&nbsp;خو داؤد ورته وفرمائيل، ”زما وروڼو، مالِک خُدائ چې مونږ له څۀ راکړى دى نو په هغې کښې شومتوب مۀ کوئ، هغۀ زمونږ حِفاظت وکړو او په لښکر باندې يې فتح راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7493, '1 Samuel 30:24', '1 Samuel', 30, 24, '&nbsp;چې تاسو څۀ وايئ نو هغې ته هيڅ څوک هم نۀ راضى کيږى. هر څۀ به داسې تقسيميږى، هر څوک چې وروستو د سامان سره پاتې وى نو هغۀ ته به هم دومره حِصه ملاويږى چې څومره هغه کسان اخلى چې جنګ له تلى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7494, '1 Samuel 30:25', '1 Samuel', 30, 25, '&nbsp;داؤد دا قانون جوړ کړو او دا تر نن ورځې پورې په بنى اِسرائيلو کښې منلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7495, '1 Samuel 30:26', '1 Samuel', 30, 26, '&nbsp;کله چې داؤد صِقلاج ته راواپس شو، نو هغۀ خپلو ملګرو له په مالِ غنيمت کښې د دې پېغام سره برخه ولېږله چې هغوئ د يهوداه مشران وُو، ”دا ستاسو دپاره په هغه مالِ غنيمت کښې تُحفه ده چې مونږ د مالِک خُدائ د دشمنانو نه اخستے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7496, '1 Samuel 30:27', '1 Samuel', 30, 27, '&nbsp;هغۀ دا تُحفه د بيت‌ايل خلقو، د يهوداه په جنوبى حِصه کښې د راما خلقو له او د يتير په ښارونو کښې خلقو له ولېږله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7497, '1 Samuel 30:28', '1 Samuel', 30, 28, '&nbsp;ورسره د عروعير، سِفموت، استموع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7498, '1 Samuel 30:29', '1 Samuel', 30, 29, '&nbsp;رَکل، د يرحمئيل او د قينى ښارونو له،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7499, '1 Samuel 30:30', '1 Samuel', 30, 30, '&nbsp;او د حُرمه، د بورعسان، او د عتاک د ښارونو خلقو له،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7500, '1 Samuel 30:31', '1 Samuel', 30, 31, '&nbsp;او د حبرون. هغۀ دا هغه ټولو ځايونو ته ولېږله چرته چې دے او د هغۀ سړى ګرځېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');